def solve(s, k):
    n = len(s)
    count = [0] * 26
    for c in s:
        count[ord(c) - ord('a')] += 1

    odd_count = 0
    for i in range(26):
        if count[i] % 2 != 0:
            odd_count += 1
            if odd_count > 1:
                return "NO"
    if odd_count > 1:
        return "NO"

    for i in range(26):
        if count[i] % 2 != 0:
            k -= count[i] - 1
            if k < 0:
                return "NO"

    return "YES"

