def count_older_passengers(details):
    count = 0
    for detail in details:
        age = int(detail[11:13])
        if age > 60:
            count += 1
    return count

def matrixScore(nums):
    n, m = len(nums), len(nums[0])
    for i in range(n):
        if nums[i][0] == 0:
            for j in range(m):
                nums[i][j] = 1 - nums[i][j]
    for j in range(1, m):
        count = sum([1 for row in nums if row[j] == 1])
        if count < n // 2:
            for i in range(n):
                nums[i][j] = 1 - nums[i][j]
    return sum([max(row) for row in nums])

def maxStrength(nums):
    if not nums:
        return 0

    max_strength = 1
    is_negative = False
    is_zero = False

    for num in nums:
        if num == 0:
            is_zero = True
            break
        elif num < 0:
            is_negative = True

    if is_zero:
        return 0

    for num in nums:
        if num < 0:
            max_strength *= num

    return max_strength

def minExtraChar(s, dictionary):
    n = len(s)
    dp = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        dp[i] = dp[i + 1] + 1
        for word in dictionary:
            if i + len(word) <= n and s[i: i + len(word)] == word:
                dp[i] = min(dp[i], dp[i + len(word)])
    return dp[0]

def buy_chocolates(prices, money):
    prices.sort()
    for i in range(len(prices) - 1):
        if prices[i] + prices[i + 1] <= money:
            return money - (prices[i] + prices[i + 1])
    return money

def count_adjacent_same_color(n, queries):
    # Initialize the result array
    result = [0] * len(queries)

    # Iterate over each query
    for i, (index, color) in enumerate(queries):
        # Set the color of the current element
        nums[index] = color

        # Count the number of adjacent elements with the same color
        count = 0
        for j in range(index - 1, -1, -1):
            if nums[j] == nums[index]:
                count += 1
            else:
                break

        # Count the number of adjacent elements with the same color
        count += 1
        for j in range(index + 1, n):
            if nums[j] == nums[index]:
                count += 1
            else:
                break

        # Store the result
        result[i] = count

    return result

def sum_of_powers(nums):
    MOD = 10**9 + 7
    n = len(nums)
    nums.sort()
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(i + 1):
            dp[i][j] = (dp[i - 1][j] + dp[i - 1][j - 1]) % MOD
            if j > 0:
                dp[i][j] = (dp[i][j] + nums[i - 1] * dp[i - 1][j - 1]) % MOD
    return sum(dp[n]) % MOD

def min_operations(nums):
    n = len(nums)
    if nums[0] != 1 or nums[-1] != n:
        return -1
    for i in range(1, n-1):
        if nums[i] != i+1 and nums[i] != n-i:
            return -1
    return n-1

def longest_semi_repetitive(s):
    n = len(s)
    max_len = 1
    for i in range(n):
        count = 1
        for j in range(i+1, n):
            if s[j] == s[j-1]:
                count += 1
                if count > 2:
                    break
            else:
                count = 1
        max_len = max(max_len, count)
    return max_len

def losers(n, k):
