    for i in range(1, n+1):
        if i % k == 0:
            losers.append(i)
    return sorted(losers)

def check_original_array(derived):
    n = len(derived)
    original = [0] * n
    original[0] = derived[0]
    for i in range(1, n):
        original[i] = original[i-1] ^ derived[i]
    return all(original[i] == derived[i] for i in range(n))

def min_length(s):
    i = 0
    while i < len(s) - 1:
        if s[i] == 'A' and s[i+1] == 'B':
            s = s[:i] + s[i+2:]
            i = 0
        elif s[i] == 'C' and s[i+1] == 'D':
            s = s[:i] + s[i+2:]
            i = 0
        else:
