def punishment_number(n):
    def is_valid_partition(s):
        if len(s) == 0:
            return False
        if len(s) == 1:
            return True
        if len(s) == 2:
            return int(s) == int(s[0]) + int(s[1])
        for i in range(1, len(s)):
            if int(s[:i]) + int(s[i:]) == int(s):
                return True
        return False

    total = 0
    for i in range(1, n + 1):
        square = i * i
        if is_valid_partition(str(square)):
            total += square
    return total

def paint_walls(cost, time):
    n = len(cost)
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        dp[i] = min(dp[i - 1] + cost[i - 1], dp[i - 1] + time[i - 1])
    return dp[n]

def minCost(nums, x):
    n = len(nums)
    dp = [0] * n
    for i in range(n):
        dp[i] = nums[i]
        for j in range(i):
            dp[i] = min(dp[i], dp[j] + nums[i] - nums[j] * (i - j))
    return sum(dp) + x * (n - 1)

def min_k_avoiding_array(n, k):
    # Initialize the array with the first n-1 positive integers
    array = list(range(1, n))

    # Iterate over the array
    for i in range(n-1):
        # Check if the current element and the next element sum to k
        if array[i] + array[i+1] == k:
            # If they do, remove the next element from the array
            array.pop(i+1)

    # Return the sum of the array
    return sum(array)

def minCost(s):
    n = len(s)
    cost = 0
    for i in range(n):
        if s[i] != '0':
            cost += i + 1
        else:
            cost += n - i
    return cost

def remove_trailing_zeros(num):
