def is_fascinating(n):
    concatenated = str(n) + str(2 * n) + str(3 * n)
    return set(concatenated) == set('123456789')

def can_traverse_all_pairs(nums):
    def gcd(a, b):
        if b == 0:
            return a
        return gcd(b, a % b)

    n = len(nums)
    visited = [False] * n
    stack = [0]
    while stack:
        node = stack.pop()
        visited[node] = True
        for i in range(n):
            if not visited[i] and gcd(nums[node], nums[i]) > 1:
                stack.append(i)
    return all(visited)

def smallest_string(s):
    n = len(s)
    for i in range(n):
        if s[i] != 'a':
            s = s[:i] + chr(ord('a') - (ord(s[i]) - ord('a'))) + s[i+1:]
            break
    return s

def count_beautiful_pairs(nums):
    def gcd(a, b):
        if b == 0:
            return a
        return gcd(b, a % b)

    def is_coprime(a, b):
        return gcd(a, b) == 1

    count = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if is_coprime(nums[i][0], nums[j][-1]):
                count += 1
    return count

def longestEqualSubarray(nums, k):
    n = len(nums)
    max_len = 1
    count = [1] * n
    for i in range(1, n):
        if nums[i] == nums[i - 1]:
            count[i] = count[i - 1] + 1
            max_len = max(max_len, count[i])
        else:
            count[i] = 1
    for i in range(n - 2, -1, -1):
        if nums[i] == nums[i + 1]:
            count[i] = count[i + 1] + 1
            max_len = max(max_len, count[i])
        else:
            count[i] = 1
    return max_len

def solve(nums, moveFrom, moveTo):
    # Create a dictionary to store the positions of marbles
    positions = {num: i for i, num in enumerate(nums)}

    # Create a list to store the final positions of marbles
    final_positions = []

    # Iterate over the moves
    for i in range(len(moveFrom)):
        # Move all marbles from moveFrom[i] to moveTo[i]
        for j in range(moveFrom[i]):
            final_positions.append(moveTo[i])

        # Update the positions of marbles
        for num in moveFrom[i]:
            positions[num] = moveTo[i]

    # Sort the final positions
    final_positions.sort()

    return final_positions

def min_operations(num1: int, num2: int) -> int:
    if num1 < num2:
        return -1
    num1 -= num2
    count = 0
    while num1 > 0:
        if num1 >= 2:
            num1 -= 2
            count += 1
        elif num1 >= 4:
            num1 -= 4
            count += 1
        elif num1 >= 8:
            num1 -= 8
            count += 1
        elif num1 >= 16:
            num1 -= 16
            count += 1
        elif num1 >= 32:
            num1 -= 32
            count += 1
        elif num1 >= 64:
            num1 -= 64
            count += 1
        else:
            return -1
    return count

def maxSum(nums1, nums2, queries):
    n = len(nums1)
    nums1.sort()
    nums2.sort()
    res = []
    for x, y in queries:
        i, j = 0, 0
        while i < n and nums1[i] < x:
            i += 1
        while j < n and nums2[j] < y:
            j += 1
        if i == n or j == n:
            res.append(-1)
        else:
            res.append(nums1[i] + nums2[j])
    return res

def sum_of_squares(nums):
    n = len(nums)
    special_elements = [nums[i] for i in range(n) if n % (i+1) == 0]
    return sum([x**2 for x in special_elements])

def partition(nums):
    nums.sort()
    return abs(nums[-1] - nums[0])

def maxNumberOfFamilies(words):
    word_dict = {}
    for word in words:
        if word not in word_dict:
            word_dict[word] = 1
        else:
            word_dict[word] += 1

    max_pairs = 0
    for word, count in word_dict.items():
        if count == 1:
            max_pairs += 1
        elif count == 2:
            max_pairs += 1
        elif count == 3:
            max_pairs += 1
        else:
            max_pairs += 2

    return max_pairs

def special_permutations(nums):
    n = len(nums)
    MOD = 10**9 + 7
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(i + 1):
            if j == 0 or nums[j - 1] % nums[i - 1] == 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1]) % MOD
            if nums[i - 1] % nums[j - 1] == 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j]) % MOD

    return sum(dp[n]) % MOD

def sum_imbalance_numbers(nums):
    n = len(nums)
    imbalance_sum = 0
    for i in range(n):
        imbalance_count = 0
        for j in range(i+1, n):
            if nums[j] - nums[i] > 1:
                imbalance_count += 1
        imbalance_sum += imbalance_count
    return imbalance_sum

def max_length(x, y, z):
    if x >= y:
        return (x + 1) * 2 + (z + 1) * 2
    else:
        return (y + 1) * 2 + (z + 1) * 2

def min_length(words):
    n = len(words)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        dp[i][i] = len(words[i - 1])
        for j in range(i + 1, n + 1):
            dp[i][j] = min(dp[i][j - 1] + len(words[j - 1]), dp[i - 1][j] + len(words[i - 1]))
    return dp[1][n]

def max_jumps(nums, target):
    n = len(nums)
    dp = [0] * n
    dp[0] = 0
    for i in range(1, n):
        for j in range(i):
            if abs(nums[i] - nums[j]) <= target and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
        if dp[i] == 0:
            return -1
    return dp[-1]

def count_complete_subarrays(nums):
    n = len(nums)
    count = 0
    for i in range(n):
        distinct = set()
        for j in range(i, n):
            distinct.add(nums[j])
            if len(distinct) == len(set(nums)):
                count += 1
    return count

def max_distance(mainTank, additionalTank):
    total_distance = 0
    while mainTank > 0:
        if mainTank >= 5:
            mainTank -= 5
            additionalTank += 1
        else:
            break
        total_distance += 10
    return total_distance

def longest_subarray(nums, threshold):
    l = 0
    max_length = 0
    for r in range(len(nums)):
        if nums[r] % 2 == 0 and all(nums[i] % 2 != nums[i + 1] % 2 for i in range(r)):
            while nums[l] % 2 != 0 or (r - l + 1) > threshold:
                l += 1
            max_length = max(max_length, r - l + 1)
    return max_length

def numberOfGoodSubarraySplits(nums):
    MOD = 10**9 + 7
    n = len(nums)
    count = 0
    for i in range(n):
        if nums[i] == 1:
            count += 1
        else:
            break
    if count == 0:
        return 0
    else:
        count = 1
        for i in range(count, n):
            if nums[i] == 1:
                count += 1
            else:
                break
        return count

def continuous_subarrays(nums):
    n = len(nums)
    left = [0] * n
    right = [0] * n
    left[0] = right[0] = 0
    for i in range(1, n):
        if nums[i] == nums[i - 1]:
            left[i] = left[i - 1] + 1
        else:
            left[i] = 0
    for i in range(n - 2, -1, -1):
        if nums[i] == nums[i + 1]:
            right[i] = right[i + 1] + 1
        else:
            right[i] = 0
    total = 0
    for i in range(n):
        total += left[i] * right[i]
    return total

def maxAlternatingSubarrayLength(nums):
    n = len(nums)
    if n < 2:
        return -1
    dp = [0] * n
    dp[0] = 1
    for i in range(1, n):
        if nums[i] == nums[i-1] + 1:
            dp[i] = dp[i-1] + 1
        else:
            dp[i] = 1
    return max(dp)

def prime_number_pairs(n):
    primes = [i for i in range(2, n+1) if all(i % p != 0 for p in range(2, int(i**0.5)+1))]
    pairs = []
    for i in range(len(primes)):
        for j in range(i+1, len(primes)):
            if primes[i] + primes[j] == n:
                pairs.append([primes[i], primes[j]])
    pairs.sort()
    return pairs

def canMakeAllZero(nums, k):
    total = sum(nums)
    if total % k != 0:
        return False
    target = total // k
    for num in nums:
        if num != target:
            return False
    return True

def min_changes(s, k):
    n = len(s)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        dp[i][1] = sum(1 for j in range(i) if s[j] != s[i - 1 - j])
    for d in range(2, n // 2 + 1):
        for i in range(1, n - d + 1):
            j = i + d
            dp[j][d] = min(dp[i][d - 1] + dp[j][d - 1], dp[i][d] + dp[j][d - 1])
            for k in range(2, d):
                dp[j][d] = min(dp[j][d], dp[i][k] + dp[j - k][d - k] + dp[i + k][d - k])
    return dp[-1][-1]

def split_strings(words, separator):
    result = []
    for word in words:
        for i in range(len(word)):
            if word[i] == separator:
                result.append(word[:i])
                result.append(word[i+1:])
                break
    return result

def solve(n, x):
    MOD = 10**9 + 7
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for j in range(1, i + 1):
            if j**x <= i:
                dp[i] = (dp[i] + dp[i - j**x]) % MOD
    return dp[n]

def min_beautiful_substrings(s):
    def is_beautiful(s):
        if s[0] == '0':
            return False
        return int(s, 2) % 5 == 0

    def dfs(start, count):
        if start == len(s):
            return count
        if is_beautiful(s[start:]):
            return dfs(start + 1, count + 1)
        return min(dfs(start + i, count + 1) for i in range(1, len(s) - start + 1) if is_beautiful(s[start:start + i]))

    return dfs(0, 0)

def longest_valid_substring(word, forbidden):
    n = len(word)
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        for j in range(i):
            if word[j:i] in forbidden:
                dp[i] = max(dp[i], dp[j])
            else:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

def faulty_keyboard(s):
    result = ""
    for char in s:
        if char == 'i':
            result = result[::-1]
        else:
            result += char
    return result

def sort_vowels(s):
    vowels = 'aeiouAEIOU'
    vowels_indices = [i for i, char in enumerate(s) if char in vowels]
    vowels_sorted = sorted([s[i] for i in vowels_indices])
    result = list(s)
    for i, char in enumerate(s):
        if char in vowels:
            result[vowels_indices[i]] = vowels_sorted.pop(0)
    return ''.join(result)

def min_split(nums):
    freq = {}
    for num in nums:
        freq[num] = freq.get(num, 0) + 1

    dominant = max(freq, key=freq.get)
    count = freq[dominant]

    for i in range(len(nums) - 1, 0, -1):
        if count * 2 > i + 1:
            return i

    return -1

def maxBeauty(nums, k):
    n = len(nums)
    nums.sort()
    max_beauty = 1
    for i in range(1, n):
        if nums[i] - nums[i - 1] <= k:
            max_beauty = max(max_beauty, i + 1)
    return max_beauty

def maxScore(nums, x):
    n = len(nums)
    dp = [0] * n
    dp[0] = nums[0]
    for i in range(1, n):
        if nums[i] % 2 == 0:
            dp[i] = max(dp[i-1] + nums[i], dp[i-1] - x)
        else:
            dp[i] = max(dp[i-1] + nums[i], dp[i-1])
    return max(dp)

def maxSum(nums):
    def max_digit(n):
        while n > 0:
            n = n // 10
        return n

    max_sum = -1
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if max_digit(nums[i]) == max_digit(nums[j]):
                max_sum = max(max_sum, nums[i] + nums[j])
    return max_sum

def count_interesting_subarrays(nums, modulo, k):
    n = len(nums)
    ans = 0
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = (prefix[i] + nums[i]) % modulo
    for i in range(n):
        cnt = prefix[i + 1] - prefix[i] + 1
        if cnt % modulo == k:
            ans += 1
        for j in range(i + 1, n):
            cnt += nums[j] - nums[i]
            if cnt % modulo == k:
                ans += 1
    return ans

def can_split(nums, m):
    def dfs(i, total, count, used):
        if i == len(nums):
            return count == n
        for j in range(i, len(nums)):
            if not used[j] and (j == i or nums[j] >= nums[j-1] + m) and (j == i or nums[j] >= total + m):
                used[j] = True
                if dfs(j+1, total + nums[j], count + 1, used):
                    return True
                used[j] = False
        return False

    n = len(nums)
    return dfs(0, 0, 0, [False]*len(nums))

def count_pairs(nums, target):
    count = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if nums[i] + nums[j] < target:
                count += 1
    return count

def max_groups(usageLimits):
    n = len(usageLimits)
    groups = [0] * n
    groups[0] = 1
    for i in range(1, n):
        groups[i] = min(groups[i-1], usageLimits[i-1])
    return sum(groups)

def stepping_numbers(low, high):
    MOD = 10**9 + 7
    low = int(low)
    high = int(high)
    low_digits = len(str(low))
    high_digits = len(str(high))
    if low_digits != high_digits:
        return 0
    if low_digits == 1:
        return high - low + 1
    stepping_numbers = [0] * (10**low_digits)
    stepping_numbers[0] = 1
    for i in range(1, 10**low_digits):
        if i % 10 == 0:
            stepping_numbers[i] = stepping_numbers[i - 1]
        else:
            for j in range(9, -1, -1):
                if i + j < 10**low_digits:
                    stepping_numbers[i + j] = (stepping_numbers[i + j] + stepping_numbers[i]) % MOD
    return stepping_numbers[high] - stepping_numbers[low - 1]

