                dp[i%2][j+1] = (dp[i%2][j+1] + dp[(i+1)%2][j]) % MOD
            if j > 0:
                dp[i%2][j] = (dp[i%2][j] + dp[(i+1)%2][j-1]) % MOD
            if j > 0 and i > 0:
                dp[i%2][j] = (dp[i%2][j] + dp[(i+1)%2][j-1]) % MOD
            if j > 0 and i > 0 and s[i-1] == t[i-1]:
