        prefix_sum[i] = prefix_sum[i - 1] + infinite_nums[i - 1]
    dp = [0] * (target + 1)
    dp[0] = -1
    for i in range(1, 2 * n + 1):
        for j in range(target, -1, -1):
            if dp[j] != -1 and j + infinite_nums[i - 1] <= target:
                dp[j + infinite_nums[i - 1]] = max(dp[j + infinite_nums[i - 1]], i - 1)
