        return len(set(s))

    def partition(s, k):
        if count_distinct_chars(s) <= k:
            return 1
        else:
            max_partitions = 0
            for i in range(len(s)):
                if count_distinct_chars(s[:i+1]) <= k:
                    max_partitions = max(max_partitions, partition(s[i+1:], k))
            return max_partitions + 1

    return partition(s, k)

