def count_non_ddos_strings(s):
    MOD = 998244353
    n = len(s)
    dp = [[0] * 26 for _ in range(26)]
    for i in range(4):
        dp[ord(s[i]) - ord('A')][ord(s[i + 1]) - ord('A')] += 1
    for i in range(4, n):
        for j in range(26):
            dp[j][ord(s[i]) - ord('A')] += dp[j][ord(s[i - 1]) - ord('A')]
            dp[j][ord(s[i]) - ord('A')] %= MOD
    ans = 0
    for i in range(26):
        for j in range(26):
            ans += dp[i][j] * dp[j][i]
            ans %= MOD
    return ans

