def solve_problem(N, M, A, S):
    # Initialize the sets
    sets = [set() for _ in range(N)]
    for i in range(N):
        for j in range(A[i]):
            sets[i].add(S[i][j])

    # Initialize the operations
    operations = 0

    # While there are sets with at least one common element
    while any(len(sets[i]) > 1 for i in range(N)):
        # Find the two sets with at least one common element
        for i in range(N):
            for j in range(i+1, N):
                if sets[i] & sets[j]:
                    # Remove the two sets and add their union
                    sets[i] = sets[j] = sets[i] | sets[j]
                    operations += 1
                    break

    # If one can obtain a set containing both 1 and M, print the minimum number of operations required to obtain it; if it is impossible, print -1 instead
    if any(1 in s and M in s for s in sets):
        return operations
    else:
        return -1
