def find_cycle_helper(start, adj_list, visited, cycle):
    visited[start] = True
    cycle.append(start)
    for neighbor in adj_list[start]:
        if not visited[neighbor]:
            cycle = find_cycle_helper(neighbor, adj_list, visited, cycle)
        elif len(cycle) > 1:
            cycle = cycle[1:]
            break
    return cycle
