def count_holeless_squares(H, W, N, a, b):
    # Initialize a 2D array to store the status of each square
    grid = [[0 for _ in range(W+1)] for _ in range(H+1)]

    # Mark the holed squares
    for i, j in zip(a, b):
        grid[i][j] = 1

    # Count the number of holeless squares
    count = 0
    for i in range(1, H+1):
        for j in range(1, W+1):
            if grid[i][j] == 0:
                # Check if the square is holeless
                for k in range(1, min(H-i+1, W-j+1)+1):
                    if grid[i+k-1][j+k-1] == 1:
                        break
                else:
                    count += 1

    return count
