def game_winner():
    # Read the grid from stdin
    grid = [list(map(int, input().split())) for _ in range(3)]

    # Function to check if a sequence of the same color exists
    def check_sequence(grid, color):
        for i in range(3):
            for j in range(3):
                if grid[i][j] == color:
                    if i < 2 and grid[i+1][j] == color:
                        return True
                    if j < 2 and grid[i][j+1] == color:
                        return True
                    if i < 2 and j < 2 and grid[i+1][j+1] == color:
                        return True
                    if i < 2 and j > 0 and grid[i+1][j-1] == color:
                        return True
                    if j < 2 and i > 0 and grid[i-1][j+1] == color:
                        return True
                    if i > 0 and j < 2 and grid[i-1][j-1] == color:
                        return True
        return False

    # Function to check if there are any white cells left
    def check_white_cells(grid):
        for i in range(3):
            for j in range(3):
                if grid[i][j] == 0:
                    return True
        return False

    # Function to determine the winner
    def determine_winner(grid):
        # Check if there are three consecutive cells of the same color
        for i in range(3):
            for j in range(3):
                if check_sequence(grid, grid[i][j]):
                    return "Takahashi" if grid[i][j] > 0 else "Aoki"
        # Check if there are any white cells left
        if check_white_cells(grid):
            return "Takahashi" if sum(sum(row) for row in grid) > 0 else "Aoki"
        # If no three consecutive cells of the same color and no white cells left, the game ends
        return "Takahashi" if sum(sum(row) for row in grid) > 0 else "Aoki"

    # Determine the winner and print the result
    print(determine_winner(grid))

