def solve():
    N, M = map(int, input().split())
    K = [0] * M
    C = [0] * M
    edges = []
    for i in range(M):
        K[i], C[i] = map(int, input().split())
        for j in range(K[i]):
            A = int(input())
            edges.append((A, A, C[i]))
        edges.sort()

    # Build a graph
    graph = [[] for _ in range(N)]
    for u, v, w in edges:
        graph[u-1].append((v-1, w))
        graph[v-1].append((u-1, w))

    # Find the minimum spanning tree
    visited = [False] * N
    total_weight = 0
    for u in range(N):
        if not visited[u]:
            stack = [(u, 0)]
            while stack:
                v, w = stack.pop()
                if visited[v]:
                    continue
                visited[v] = True
                total_weight += w
                for nv, nw in graph[v]:
                    if not visited[nv]:
                        stack.append((nv, nw))

    # Check if the graph is connected
    if not all(visited):
        print(-1)
    else:
        print(total_weight)

