def max_prime_distance(nums):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    primes = [i for i in range(len(nums)) if is_prime(nums[i])]
    if len(primes) < 2:
        return 0

    max_distance = 0
    for i in range(len(primes)):
        for j in range(i + 1, len(primes)):
            max_distance = max(max_distance, abs(primes[j] - primes[i]))

