        if amount == 0:
            return 1
        if amount < 0:
            return 0
        count = 0
        for coin in coins:
            count += count_amounts(coins, amount - coin)
        return count

    def find_kth_smallest_amount(coins, k):
        total_amounts = sum(count_amounts(coins, amount) for amount in range(1, k + 1))
        return k - total_amounts

    return find_kth_smallest_amount(coins, k)

