    for i in range(zero + 1):
        for j in range(one + 1):
            if i > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j]) % MOD
            if j > 1:
                dp[i][j] = (dp[i][j] + dp[i][j - 2]) % MOD
    return dp[zero][one]

def permutation_difference(s, t):
    s_dict = {}
    t_dict = {}
    for i in range(len(s)):
        s_dict[s[i]] = s_dict.get(s[i], []) + [i]
    for i in range(len(t)):
        t_dict[t[i]] = t_dict.get(t[i], []) + [i]
    return sum(abs(s_dict[s][i] - t_dict[t][i]) for s, t in zip(s, t))

def max_energy(energy, k):
    energy.sort()
    max_energy = 0
    for i in range(len(energy)):
        if i + k < len(energy):
            max_energy += energy[i + k]
        else:
            break
    return max_energy

def is_special(nums):
    for i in range(len(nums) - 1):
        if (nums[i] % 2 == nums[i + 1] % 2):
            return False
    return True

def sum_digit_diff(nums):
    def digit_diff(a, b):
        return sum(1 for i in range(len(str(a))) if str(a)[i] != str(b)[i])

    return sum(digit_diff(a, b) for a in nums for b in nums if a != b)

def ways_to_reach_stair(k):
    if k == 0:
        return 2
    elif k == 1:
        return 4
    else:
        return 2 * (2 ** (k - 1))

def count_good_pairs(nums1, nums2, k):
    count = 0
    for i in range(len(nums1)):
        for j in range(len(nums2)):
            if nums1[i] % nums2[j] == 0 and nums1[i] // nums2[j] % k == 0:
                count += 1
    return count

def compress(word):
    comp = ""
    for i in range(len(word)):
        count = 1
        while i + 1 < len(word) and word[i] == word[i + 1]:
            i += 1
            count += 1
        comp += str(count) + word[i]
    return comp

def maxSubsequenceSum(nums, queries):
    MOD = 10**9 + 7
    n = len(nums)
    dp = [0] * (n + 1)
    dp[0] = nums[0]
    for i in range(1, n):
        dp[i] = max(dp[i - 1], nums[i])
    max_sum = dp[-1]
    for pos, x in queries:
        if pos == 0:
            max_sum = max(max_sum, dp[-1] - nums[pos])
        else:
            max_sum = max(max_sum, dp[pos - 1] + x - nums[pos])
    return max_sum % MOD

def min_partitions(s):
    # Count the frequency of each character
    freq = {}
    for char in s:
        if char in freq:
            freq[char] += 1
        else:
            freq[char] = 1

    # Find the maximum frequency
    max_freq = max(freq.values())

    # If all characters have the same frequency, return 1
    if max_freq == len(s):
        return 1

    # If not, return the number of partitions
    return max_freq

def find_xor(nums):
    xor = 0
    for num in nums:
        xor ^= num
    return xor

def find_occurrences(nums, queries, x):
    result = []
    for q in queries:
        count = 0
        for i in range(len(nums)):
            if nums[i] == x:
                count += 1
                if count == q:
                    result.append(i)
                    break
        else:
            result.append(-1)
    return result
